#!/usr/bin/env python3
"""Bounded visual B→A recovery using the existing private F1 runtime bundle.

Local --package freezes selected source files only. Cloud execution reuses
f1_run deployment/build and the unchanged Factory/Oracle task owner.
"""
import argparse
import gzip
import importlib.util
import json
import os
from pathlib import Path
import shutil
import subprocess
import tarfile
import threading
import time
import xml.etree.ElementTree as ET

# Generated by the installed official rosdep resolver for Ubuntu Noble/Jazzy.
ROS_PYTHON_APT = {
    'python3-argcomplete': ['python3-argcomplete'],
    'python3-empy': ['python3-empy'],
    'python3-importlib-metadata': ['python3-importlib-metadata'],
    'python3-lark-parser': ['python3-lark'],
    'python3-numpy': ['python3-numpy'],
    'python3-yaml': ['python3-yaml'],
}


def declared_ros_python_dependencies(prefix):
    """Read installed ROS runtime declarations; rosdep owns Ubuntu mapping."""
    pending = ['rclpy', 'rosidl_runtime_py', 'message_filters', 'sensor_msgs',
               'diagnostic_msgs', 'geometry_msgs', 'std_msgs']
    seen, dependencies = set(), set()
    while pending:
        name = pending.pop()
        if name in seen:
            continue
        seen.add(name)
        manifest = prefix/name/'package.xml'
        if not manifest.exists():
            continue
        for item in ET.parse(manifest).getroot():
            if item.tag not in ('depend', 'exec_depend'):
                continue
            dependency = (item.text or '').strip()
            if dependency.startswith('python3-'):
                dependencies.add(dependency)
            elif (prefix/dependency/'package.xml').exists():
                pending.append(dependency)
    return sorted(dependencies), sorted(seen)


def package(output, root, so101, native_install=None):
    output.mkdir(parents=True, exist_ok=False)
    files = subprocess.check_output(['git', 'ls-files', 'tools', 'fishbot.sh',
        'experiments/kaggle', 'workspaces/fishbot_mujoco_ws/src'], cwd=root,
        text=True).splitlines()
    # This new adapter may not have been committed yet.
    files = sorted(set(files + ['experiments/kaggle/f1_visual_recovery.py']))
    sources = []
    with tarfile.open(output/'f1-visual-source.tar.gz.bin', 'w:gz') as archive:
        for relative in files:
            path = root/relative
            if path.is_file():
                archive.add(path, arcname='fishbot/'+relative, recursive=False)
                sources.append('fishbot/'+relative)
        for path in sorted((so101/'experiments/colab-twin').glob('*.py')):
            archive.add(path, arcname='so101/'+str(path.relative_to(so101)))
        for relative in ['experiments/colab-twin/requirements.txt',
                         'experiments/graspgenx-demo/setup.sh', 'LICENSE']:
            path = so101/relative
            if path.is_file():
                archive.add(path, arcname='so101/'+relative)
        archive.add(so101/'workspaces/so101_ws/src/so101_mujoco/models',
                    arcname='so101/workspaces/so101_ws/src/so101_mujoco/models')
    provenance = {'source_commit': subprocess.check_output(['git', 'rev-parse', 'HEAD'],
        cwd=root, text=True).strip(), 'files': sources,
        'working_source_snapshot': True, 'models_or_runtime_cache_included': False,
        'acceptance': False}
    (output/'source-provenance.json').write_text(json.dumps(provenance, indent=2)+'\n')
    shutil.copyfile(__file__, output/'f1_visual_recovery.py')
    if native_install:
        shutil.copyfile(native_install, output/'native-install.tar.gz.bin')
    print(json.dumps({'output': str(output), 'archive_bytes':
          (output/'f1-visual-source.tar.gz.bin').stat().st_size}))


class OverviewRecorder:
    """Encode actual new overview JPEGs; preserve irregular source timestamps."""
    def __init__(self, runtime, output):
        self.runtime, self.output = runtime, output
        self.stop = threading.Event()
        self.thread = threading.Thread(target=self.record, daemon=True)
        self.thread.start()

    def record(self):
        encoder = None
        previous = None
        count = 0
        try:
            with (self.output/'overview-frames.jsonl').open('w') as index:
                while not self.stop.wait(.20):
                    directory = self.runtime/'frames'
                    metadata_path = directory/'latest.json'
                    if not metadata_path.exists():
                        continue
                    try:
                        metadata = json.loads(metadata_path.read_text())
                        key = (metadata.get('episode_id'), metadata.get('stamp'))
                        if key == previous:
                            continue
                        jpeg = (directory/'latest.jpg').read_bytes()
                    except (OSError, ValueError):
                        continue
                    if encoder is None:
                        encoder = subprocess.Popen(['ffmpeg', '-hide_banner', '-loglevel',
                            'warning', '-f', 'image2pipe', '-framerate', '2', '-vcodec',
                            'mjpeg', '-i', '-', '-an', '-c:v', 'libx264', '-preset', 'fast',
                            '-crf', '26', '-pix_fmt', 'yuv420p', str(self.output/'overview.mp4')],
                            stdin=subprocess.PIPE)
                    encoder.stdin.write(jpeg)
                    encoder.stdin.flush()
                    index.write(json.dumps({'video_frame': count, 'metadata': metadata,
                        'sampled_wall_time': time.time()})+'\n')
                    index.flush()
                    previous, count = key, count+1
        except Exception as error:
            (self.output/'overview-error.txt').write_text(repr(error))
        finally:
            if encoder:
                encoder.stdin.close()
                try:
                    encoder.wait(timeout=30)
                except subprocess.TimeoutExpired:
                    encoder.terminate()
            (self.output/'overview-receipt.json').write_text(json.dumps({
                'actual_rendered_frames': count, 'playback_fps': 2,
                'source_timing': 'overview-frames.jsonl; gaps are not interpolated',
                'is_task_acceptance': False}, indent=2))

    def close(self):
        self.stop.set()
        self.thread.join(timeout=35)


def cloud():
    candidates = list(Path('/kaggle/input').rglob('f1-visual-source.tar.gz.bin'))
    if len(candidates) != 1:
        raise RuntimeError('Attach exactly one selected visual source snapshot')
    bootstrap = Path('/tmp/f1-visual-bootstrap')
    bootstrap.mkdir(exist_ok=False)
    with tarfile.open(candidates[0], 'r:gz') as archive:
        archive.extractall(bootstrap, filter='data')
    base_path = bootstrap/'fishbot/experiments/kaggle/f1_run.py'
    # Preserve executable permissions/links through Kaggle dataset ingestion.
    base_path.write_text(base_path.read_text().replace(
        "rglob('native-install.tar.gz')", "rglob('native-install.tar.gz.bin')"))
    spec = importlib.util.spec_from_file_location('f1_base', base_path)
    base = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(base)
    original_run = base.run
    os.environ.update(FISHBOT_TRANSPORT_CONTROLLER='graceful', MUJOCO_GL='egl',
                      FISHBOT_REUSE_NATIVE_INSTALL='1',
                      FISHBOT_MUJOCO_DOMAIN_ID='187')

    def run(name, args, **kwargs):
        if name == 'ubuntu-index':
            for project in ['fishbot', 'so101']:
                shutil.copytree(bootstrap/project, base.WORK/project, dirs_exist_ok=True)
            shutil.copyfile(candidates[0], base.ARTIFACTS/'source-snapshot.tar.gz')
            shutil.copyfile(__file__, base.ARTIFACTS/'cloud-adapter.py')
            provenance = candidates[0].with_name('source-provenance.json')
            if provenance.exists():
                shutil.copyfile(provenance, base.ARTIFACTS/provenance.name)
        if name == 'ubuntu-dependencies':
            keys, manifests = declared_ros_python_dependencies(Path('/opt/ros/jazzy/share'))
            packages = {package for key in keys for package in ROS_PYTHON_APT.get(key, [])}
            args = list(args)+['python3-opencv', 'python3-pil', 'python3-scipy',
                               'python3-yaml', 'ffmpeg', 'libosmesa6', *sorted(packages)]
            result = original_run(name, args, **kwargs)
            vision_env = dict(os.environ, PYTHONPATH='/usr/lib/python3/dist-packages')
            vision_env.pop('PYTHONHOME', None)
            resolutions = [{'rosdep_key': key, 'apt_packages': ROS_PYTHON_APT[key],
                'basis': 'official rosdep resolve --rosdistro jazzy --os=ubuntu:noble'}
                for key in keys if key in ROS_PYTHON_APT]
            unknown = [key for key in keys if key not in ROS_PYTHON_APT]
            if unknown:
                # New declarations are resolved in this same job, never guessed
                # from an import name or postponed to a new kernel retry.
                original_run('rosdep-bootstrap', ['apt-get', 'install', '-y',
                    '--no-install-recommends', 'python3-rosdep2'], env=kwargs.get('env'), timeout=120)
                rosdep = ['/usr/bin/python3.12', shutil.which('rosdep') or '/usr/bin/rosdep']
                original_run('rosdep-initialize', rosdep+['init'], env=vision_env,
                             timeout=60, required=False)
                original_run('rosdep-runtime-index', rosdep+['update', '--rosdistro', 'jazzy'],
                             env=vision_env, timeout=180)
                added = set()
                for key in unknown:
                    resolved = subprocess.run(rosdep+['resolve', '--rosdistro', 'jazzy',
                        '--os=ubuntu:noble', key], env=vision_env, text=True,
                        capture_output=True, timeout=45)
                    apt_packages = [word for line in resolved.stdout.splitlines()
                        if line and not line.startswith('#') for word in line.split()]
                    resolutions.append({'rosdep_key': key, 'returncode': resolved.returncode,
                                        'apt_packages': apt_packages, 'stderr': resolved.stderr})
                    if resolved.returncode:
                        print('WARNING: unresolved declared Python dependency:', key, flush=True)
                    else:
                        added.update(apt_packages)
                if added:
                    original_run('ros-python-added-dependencies', ['apt-get', 'install', '-y',
                        '--no-install-recommends', *sorted(added)], env=kwargs.get('env'), timeout=180)
                    packages.update(added)
            (base.ARTIFACTS/'ros-python-runtime-dependencies.json').write_text(json.dumps({
                'source': 'installed ROS package.xml depend/exec_depend closure',
                'manifests': manifests, 'resolutions': resolutions,
                'apt_packages': sorted(packages)}, indent=2)+'\n')
            diagnostic = ('import sys,cv2,numpy; print(sys.version); '
                'print(cv2.__version__,cv2.__file__,numpy.__version__,numpy.__file__); '
                'a=cv2.aruco; d=a.getPredefinedDictionary(a.DICT_APRILTAG_36h11); '
                'm=a.drawMarker(d,0,256,borderBits=1); print(m.shape)')
            default = original_run('default-system-opencv',
                ['/usr/bin/python3', '-B', '-c', diagnostic], env=vision_env,
                timeout=30, required=False)
            selected = original_run('jazzy-system-opencv',
                ['/usr/bin/python3.12', '-B', '-c', diagnostic], env=vision_env,
                timeout=30)
            changes = []
            for relative in ['tools/cooperation_camera.py', 'tools/cooperation.launch.py']:
                source = base.WORK/'fishbot'/relative
                text = source.read_text().replace("'/usr/bin/python3'", "'/usr/bin/python3.12'")
                source.write_text(text)
                saved = base.ARTIFACTS/'cloud-compatibility-source'/relative
                saved.parent.mkdir(parents=True, exist_ok=True)
                saved.write_text(text)
                changes.append(relative)
            (base.ARTIFACTS/'system-vision-python.json').write_text(json.dumps({
                'interpreter': '/usr/bin/python3.12', 'modified_global_interpreter': False,
                'default_probe_returncode': default['returncode'],
                'jazzy_probe_returncode': selected['returncode'], 'cloud_source_files': changes}, indent=2))
            imports = ('import cooperation_station_vision,fishbot_inspection; '
                'import PIL,scipy.optimize,cv2,rclpy,message_filters; '
                'from cooperation_camera import calibration; '
                'expected=calibration((0.,0.,0.))["detector"]; '
                'print("PIL",PIL.__version__,"SciPy",scipy.__version__,"OpenCV",cv2.__version__,"required",expected); '
                'from sensor_msgs.msg import Image,CameraInfo; '
                '\nif scipy.__version__ != expected["scipy_version"] or cv2.__version__ != expected["opencv_version"]:'
                '\n raise ValueError("Installed system vision versions differ from existing detector contract")'
                '\nprint("system vision entry imports passed; zero ROS nodes")')
            isolated = ('import sys,subprocess; sys.path.insert(0,'+
                repr(str(base.WORK/'fishbot/tools'))+'); '
                'from cooperation_camera import system_vision_environment; '
                'subprocess.run(["/usr/bin/python3.12","-B","-c",'+
                repr('import sys;sys.path.insert(0,'+
                     repr(str(base.WORK/'fishbot/tools'))+');'+imports)+
                '],env=system_vision_environment(),check=True)')
            original_run('system-vision-entry-import', ['bash', '-ec',
                'source /opt/ros/jazzy/setup.bash; exec "$@"', 'vision-import',
                '/usr/bin/python3.12', '-B', '-c', isolated], env=vision_env, timeout=45)
            original_run('gpu-resource', ['nvidia-smi'], timeout=30)
            return result
        if name == 'planning-versions':
            result = original_run(name, args, **kwargs)
            python = str(base.WORK/'planning-venv/bin/python')
            original_run('model-bootstrap-tools', [python, '-m', 'pip', 'install',
                'uv', 'huggingface_hub'], timeout=180)
            env = dict(os.environ, SO101_GRASPGENX_CACHE=str(base.WORK/'graspgenx'),
                PATH=str(base.WORK/'planning-venv/bin')+':'+os.environ.get('PATH', ''))
            env.pop('PYTHONPATH', None)
            original_run('official-graspgenx-setup', ['bash', str(base.WORK/
                'so101/experiments/graspgenx-demo/setup.sh')], env=env, timeout=1200)
            original_run('model-entry-import', [str(base.WORK/'graspgenx/upstream/.venv/bin/python'),
                '-B', '-c', 'import torch; from graspgenx.serving.zmq_server import '
                'GraspGenXZMQServer; print("official model entry imports passed; no model instantiated")'],
                env=dict(env, PYTHONPATH=''), timeout=90)
            planning_env = dict(os.environ, PYTHONPATH=':'.join(map(str,
                [base.WORK/'fishbot/tools', base.WORK/'so101/experiments/colab-twin',
                 Path('/usr/lib/python3/dist-packages')])))
            original_run('planning-entry-import', ['bash', '-ec',
                'source tools/fishbot_mujoco_env.sh; exec "$@"', 'planning-import', python,
                '-B', '-c', 'import mujoco,mink,ompl; from ompl import base,geometric; '
                'import cooperation_sim,cooperation_bridge,cooperation_arm; '
                'import grasp_episode,joint_planner,placement; '
                'print("planning entry imports passed; no model/data created")'],
                cwd=base.WORK/'fishbot', env=planning_env, timeout=90)
            return result
        if name == 'factory-b-a':
            start = args.index('tools/cooperation_factory.py')
            args = list(args[:start+1])+['run', '--manifest',
                str(base.ARTIFACTS/'scene/scene-manifest.json'), '--planning-python',
                str(base.WORK/'planning-venv/bin/python'), '--output',
                str(base.ARTIFACTS/'full-run'), '--candidate', 'f1-visual-recovery',
                '--publication-mode', 'asynchronous', '--continuous-deliveries',
                'tools/config/factory_delivery/continuous-ba-orders.json',
                '--order', 'order-b', '--order', 'order-a', '--scope', 'transport',
                '--domain', '187', '--port', '9157', '--isolated-runtime']
            recorder = OverviewRecorder(base.ARTIFACTS/'full-run/runtime', base.ARTIFACTS)
            try:
                return original_run(name, args, **kwargs)
            finally:
                recorder.close()
                archived = []
                for source in base.ARTIFACTS.rglob('observer.jsonl'):
                    destination = Path(str(source)+'.gz')
                    try:
                        raw_bytes = source.stat().st_size
                        with source.open('rb') as incoming, gzip.open(destination, 'wb') as outgoing:
                            shutil.copyfileobj(incoming, outgoing)
                        with gzip.open(destination, 'rb') as verification:
                            while verification.read(1024*1024):
                                pass
                        source.unlink()
                        archived.append({'file': str(destination.relative_to(base.ARTIFACTS)),
                            'raw_bytes': raw_bytes, 'gzip_bytes': destination.stat().st_size,
                            'verification': 'full gzip decode and CRC before removing original'})
                    except Exception as error:
                        print('WARNING: retain original observer; archive failed:',
                              source, type(error).__name__, flush=True)
                        archived.append({'file': str(source.relative_to(base.ARTIFACTS)),
                                         'original_retained': source.exists(),
                                         'error_type': type(error).__name__})
                (base.ARTIFACTS/'observer-archives.json').write_text(json.dumps(archived, indent=2)+'\n')
        return original_run(name, args, **kwargs)

    def prepare(fishbot, so101, python, data, env):
        scene = base.ARTIFACTS/'scene'
        config = json.loads((fishbot/'tools/config/perception/pretrained-grasp.example.json').read_text())
        config.update(python=str(base.WORK/'graspgenx/upstream/.venv/bin/python'),
            models=str(base.WORK/'graspgenx/models'),
            descriptor=str(fishbot/'tools/config/perception/so101-graspgenx-tip-region.json'))
        grasp = base.ARTIFACTS/'pretrained-grasp.json'
        grasp.write_text(json.dumps(config, indent=2)+'\n')
        prepare_args = [str(fishbot/'tools/fishbot_cooperation.sh'), 'prepare',
            '--so101-project', str(so101), '--output', str(scene),
            '--arena-xml', 'tools/config/factory_delivery/j100-wide-arena.xml',
            '--scene-profile', 'tools/config/factory_delivery/j100-wide-profile.json',
            '--factory-config', 'tools/config/factory_delivery/j100-wide.json',
            '--continuous-delivery', 'tools/config/factory_delivery/j100-wide-entities.json',
            '--spawn', '-.9', '-1.68', '--navigation-planner', 'smac-lattice',
            '--lattice-filepath', 'tools/config/navigation_lattices/diff-r060-2cm.json',
            '--lattice-allow-reversing', '--lattice-rotation-shim', '--staging-reversing',
            '--amcl-motion-model', 'omni', '--omit-unused-native-rangefinders',
            '--queued-ros-dispatch', '--terminal-stop-heartbeat',
            '--perception-config', 'tools/config/perception/apriltag-station.example.json',
            '--pretrained-grasp-config', str(grasp)]
        run('scene-prepare', ['bash', '-ec',
            'source /opt/ros/jazzy/setup.bash; exec "$@"', 'visual-prepare',
            *prepare_args], cwd=fishbot, env=env, timeout=180)
        run('candidate-configuration', [python, str(fishbot/'experiments/kaggle/f1_candidate.py'),
            str(scene/'scene-manifest.json'), '--transport-controller-yaml',
            str(fishbot/'experiments/kaggle/graceful-j100.yaml'), '--lattice-smooth-path'],
            cwd=fishbot, env=env)
        manifest_file = scene/'scene-manifest.json'
        manifest = json.loads(manifest_file.read_text())
        manifest['render_overview'] = True
        manifest_file.write_text(json.dumps(manifest, indent=2)+'\n')
        render_code = '''import json,sys,os
from pathlib import Path
import mujoco,numpy as np
from PIL import Image
from cooperation_camera import render_depth
manifest=json.loads(Path(sys.argv[1]).read_text())
output=Path(sys.argv[2]); config=manifest['station_camera']
model=mujoco.MjModel.from_xml_path(manifest['world_xml']); data=mujoco.MjData(model)
mujoco.mj_forward(model,data)
options=mujoco.MjvOption(); options.geomgroup[:]=1; options.sitegroup[:]=0
options.flags[mujoco.mjtVisFlag.mjVIS_RANGEFINDER]=False
with mujoco.Renderer(model,height=config['height'],width=config['width']) as renderer:
 renderer.update_scene(data,camera=config['name'],scene_option=options)
 rgb=renderer.render().copy(); Image.fromarray(rgb).save(output/'static-rgbd-preflight.png')
 renderer.enable_depth_rendering(); depth=render_depth(renderer,model,data,config,options)
 np.save(output/'static-rgbd-preflight-depth.npy',depth,allow_pickle=False)
report={'scope':'isolated static query data; mj_forward only; zero mj_step and ROS goals',
 'gl_backend':os.environ.get('MUJOCO_GL'),
 'camera':config['name'],'rgb_shape':list(rgb.shape),'depth_shape':list(depth.shape),
 'finite_depth_pixels':int(np.isfinite(depth).sum()),'query_source_time':float(data.time),
 'task_acceptance':False}
(output/'static-rgbd-preflight.json').write_text(json.dumps(report,indent=2)); print(report)
'''
        render_args = ['bash', '-ec',
            'source tools/fishbot_mujoco_env.sh; exec "$@"', 'render-preflight',
            python, '-B', '-c', render_code, str(manifest_file), str(base.ARTIFACTS)]
        try:
            rendered = run('static-rgbd-render-preflight', render_args,
                cwd=fishbot, env=env, timeout=60, required=False)
        except subprocess.TimeoutExpired:
            rendered = {'returncode': 124}
        if rendered['returncode']:
            for name in ['static-rgbd-preflight.png', 'static-rgbd-preflight-depth.npy',
                         'static-rgbd-preflight.json']:
                partial = base.ARTIFACTS/name
                if partial.exists():
                    partial.rename(partial.with_name('egl-failed-'+name))
            fallback = dict(env, MUJOCO_GL='osmesa')
            run('static-rgbd-osmesa-preflight', render_args,
                cwd=fishbot, env=fallback, timeout=60)
            # The entire subsequent launch uses this explicitly recorded backend.
            env['MUJOCO_GL'] = os.environ['MUJOCO_GL'] = 'osmesa'
        return scene

    base.run, base.prepare_scene = run, prepare
    base.main()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--package', type=Path)
    parser.add_argument('--root', type=Path, default=Path(__file__).resolve().parents[2])
    parser.add_argument('--so101', type=Path)
    parser.add_argument('--native-install', type=Path)
    args = parser.parse_args()
    if args.package:
        package(args.package, args.root, args.so101, args.native_install)
    else:
        cloud()
